(base/'work/checks/gates-complete-reviewed-types.json').write_text(json.dumps({'types':types,'type_sha256':{n:sha256(t.encode()).hexdigest() for n,t in types.items()},'axioms':axioms,'all22_previous_core_and_finite_types_preserved':True},indent=2)+'\n')
